label.text:
The supplier opens the order's bill upload page on your
                                            supplier site and sends its bill there, without signing in. Each link is new;
                                            it is shown once.

Credit ${settlement.creditTotalText} · Refund ${
                                                    settlement.refundTotalText}${settlement.replaceQuantityText != '0' ?
                                                    ' · Replace ' + settlement.replaceQuantityText : ''}
